ALTER TABLE connections ADD COLUMN federation_revision BIGINT NOT NULL DEFAULT 0;
ALTER TABLE connections ADD COLUMN federation_secrets_sealed LONGBLOB NULL;
ALTER TABLE tenants ADD COLUMN identity_epoch BIGINT NOT NULL DEFAULT 0;
ALTER TABLE users MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE user_logins MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE sessions MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE auth_codes MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE refresh_tokens MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE password_reset_tickets MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE device_codes MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE operators MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE password_history MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE email_verification_tickets MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE email_notifications MODIFY subject_id VARBINARY(1280) NOT NULL;
ALTER TABLE user_grants DROP INDEX user_grants_key;
ALTER TABLE user_grants DROP COLUMN grant_key;
ALTER TABLE user_grants MODIFY user_id VARBINARY(1280) NOT NULL;
ALTER TABLE user_grants ADD COLUMN grant_key BINARY(32) AS (UNHEX(SHA2(CONCAT_WS(CHAR(10), client_id, user_id, audience), 256))) STORED;
CREATE UNIQUE INDEX user_grants_key ON user_grants (tenant_id, grant_key);
CREATE TABLE federation_attempts (tenant_id VARCHAR(64) NOT NULL, state_hash VARCHAR(128) NOT NULL, transaction_id VARCHAR(255) NOT NULL, connection_id VARCHAR(255) NOT NULL, revision BIGINT NOT NULL, identity_epoch BIGINT NOT NULL, cookie_hash VARCHAR(128) NOT NULL, origin TEXT NOT NULL, callback_url TEXT NOT NULL, issuer TEXT NOT NULL, endpoints LONGTEXT NOT NULL, sealed_proof LONGBLOB NULL, expires_at BIGINT NOT NULL, status VARCHAR(16) NOT NULL, superseded BOOLEAN NOT NULL DEFAULT FALSE, created_at BIGINT NOT NULL, PRIMARY KEY (tenant_id, state_hash), KEY federation_attempts_tx (tenant_id, transaction_id), KEY federation_attempts_expiry (expires_at), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE federated_identities (tenant_id VARCHAR(64) NOT NULL, connection_id VARCHAR(255) NOT NULL, subject VARBINARY(1024) NOT NULL, user_id VARBINARY(1280) NOT NULL, PRIMARY KEY (tenant_id, connection_id, subject), KEY federated_identities_user (tenant_id, user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE federated_tokens (tenant_id VARCHAR(64) NOT NULL, connection_id VARCHAR(255) NOT NULL, subject VARBINARY(1024) NOT NULL, sealed LONGBLOB NOT NULL, PRIMARY KEY (tenant_id, connection_id, subject), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
